    // Glossary
    'glossary.title': 'Economics Glossary',
    'glossary.description': 'Key economics terms with definitions and formulas. Use search and category filters.',
    'glossary.searchPlaceholder': 'Search term...',
    'glossary.clearSearch': 'Clear search',
    'glossary.found': 'Found',
